import torch
class Model(torch.nn.Module):
 def forward(self,x):
  return torch.pow(x,2)/2
def make():return Model().eval()

import torch
class Model(torch.nn.Module):
 def __init__(self):
  super().__init__()
  self.register_buffer('weight',torch.zeros((2, 2),dtype=torch.float64))
 def forward(self,x):
  a=torch.nn.functional.linear(x,self.weight)
  return torch.pow(a,4)/2
def make():return Model().eval()

import torch
class Model(torch.nn.Module):
 def forward(self,x):
  a,b=x.unbind()
  a.pow_(4)
  b.div_(2)
  return x,a
def make():return Model().eval()

import torch
class Model(torch.nn.Module):
 def forward(self,x):
  a=x.clone()
  x.pow_(4)
  x.div_(2)
  return a,x
def make():return Model().eval()

import torch
class Model(torch.nn.Module):
 def forward(self,x):
  d=torch.einsum("ii->i",x)
  d.pow_(2)
  d.div_(2)
  return x,d
def make():return Model().eval()

import torch
class Model(torch.nn.Module):
 def __init__(self):
  super().__init__()
  self.register_buffer('gain',torch.zeros((),dtype=torch.float64))
 def forward(self,x):
  x.div_(self.gain)
  return x.pow(2)
def make():return Model().eval()

import torch
class Model(torch.nn.Module):
 def forward(self,x):
  a=x.pow(exponent=4)
  return a.divide(2).reshape(a.numel())
def make():return Model().eval()

import torch
class Model(torch.nn.Module):
 def forward(self,x,y):
  a=torch.true_divide(x,2)
  b=y.pow(2)
  return dict(main=a+b,secondary=torch.stack([a,b]))
def make():return Model().eval()

import torch
class Model(torch.nn.Module):
 def forward(self,x):
  a,b=x.unbind()
  a.add_(b*.125)
  return a,x
def make():return Model()

import torch
class Model(torch.nn.Module):
 def __init__(self):
  super().__init__()
  self.register_buffer("w1",torch.zeros((4,4),dtype=torch.float64))
  self.register_buffer("w2",torch.zeros((2,4),dtype=torch.float64))
 def forward(self,x):
  x=torch.nn.functional.linear(x,self.w1)
  return torch.nn.functional.linear(x.square(),self.w2)
def make():return Model().eval()
